# Catálogo plano de todos os Poderes de Distinção (chave única -> dict do poder)
DADOS_PODERES_DISTINCAO_HEROIS: Dict[str, Dict[str, Any]] = {}
for _dist_nome, _dist_dados in DADOS_DISTINCOES_HEROIS.items():
    _slug_dist = ''.join(c if c.isalnum() else '_' for c in _dist_nome).strip('_')
    for _pod in _dist_dados['poderes']:
        _slug_pod = ''.join(c if c.isalnum() else '_' for c in _pod['nome']).strip('_')
        DADOS_PODERES_DISTINCAO_HEROIS[f'HA_DIST_{_slug_dist}_{_slug_pod}'] = _pod
